 3 import java.util.Date;
 4 import java.util.concurrent.BlockingQueue;
 5 import java.util.concurrent.LinkedBlockingQueue;
 6 import java.util.concurrent.ThreadPoolExecutor;
 7 import java.util.concurrent.TimeUnit;
 8 import java.util.concurrent.atomic.AtomicInteger;
 9 
10 /**
11  * @discription
12  */
13 public class ThreadPoolStudy {
14     private static AtomicInteger count = new AtomicInteger();
15 
16     private static int coreThreadSize = 5;
17 
18     private static int maxThreadSize = 10;
19 
20     private static long keepAliveTime = 60;
21 
22     private static TimeUnit timeUnit = TimeUnit.SECONDS;
23 
24     private static BlockingQueue<Runnable> taskQueue = new LinkedBlockingQueue<>(10);
25 
26     public static void main(String[] args) {
27         ThreadPoolExecutor executor = new ThreadPoolExecutor(coreThreadSize, maxThreadSize, keepAliveTime,
28                 timeUnit, taskQueue);
29         long start = new Date().getTime();
30 
31         for (int i = 0; i < 30; i++) {
32             try {
33                 executor.execute(() -> {
34                     int value = count.incrementAndGet();
35                     System.out.println("thread :"+ Thread.currentThread().getName()+" |current value:" + value);
36                     try {
37                         TimeUnit.SECONDS.sleep(1);
38                     } catch (InterruptedException e) {
39                         //do sth
40                     }
41                 });
42             } catch (Exception ex) {
43                 System.out.println("exec catch ex :" + ex.getMessage());
44             }
45 
46         }
47         long end = new Date().getTime();
48         System.out.println("time cost :" + (end - start));
49     }
50 }

